import { tv } from "tailwind-variants";

const otpField = tv({
  slots: {
    root: "flex w-full gap-2",
    input: [
      "size-8 items-center justify-center rounded-md border border-input bg-background text-center text-sm text-foreground tabular-nums shadow-sm transition-all duration-150 ease-default outline-none",
      "placeholder:text-muted-foreground",
      "focus-visible:ring-2 focus-visible:ring-ring/50",
      "data-disabled:pointer-events-none data-disabled:opacity-50",
      "data-invalid:border-destructive/50",
      "focus-visible:data-invalid:ring-destructive/50",
      "dark:bg-input/15",
    ],
    separator: "",
  },
});

export { otpField };

"use client";

import { useDirection } from "@base-ui/react";
import { OTPField as BaseOTPField } from "@base-ui/react/otp-field";

import { mergeSlotClassName } from "@/registry/sector23/lib/merge-base-ui";

import { otpField } from "./otp-field.style";

function OTPField({ className, ...props }: BaseOTPField.Root.Props) {
  const direction = useDirection();

  return (
    <BaseOTPField.Root
      data-slot="otp-field"
      className={mergeSlotClassName(otpField().root, className)}
      {...props}
      dir={direction}
    />
  );
}

function OTPFieldInput({ className, ...props }: BaseOTPField.Input.Props) {
  return (
    <BaseOTPField.Input
      data-slot="otp-field-input"
      className={mergeSlotClassName(otpField().input, className)}
      {...props}
    />
  );
}

function OTPFieldSeparator({
  className,
  ...props
}: BaseOTPField.Separator.Props) {
  return (
    <BaseOTPField.Separator
      data-slot="otp-field-separator"
      className={mergeSlotClassName(otpField().separator, className)}
      {...props}
    />
  );
}

export { OTPField, OTPFieldInput, OTPFieldSeparator };
